# Generated by manage.py generate_test_cases.
"""Verify field-aware linking without copying bytes or replacing attachments."""

from typing import Any
from unittest.mock import patch

from django.contrib.auth.models import Permission
from django.contrib.contenttypes.models import ContentType
from django.core.files.uploadedfile import SimpleUploadedFile
from django.http import HttpResponse
from django.urls import reverse
from rest_framework.response import Response
from rest_framework.test import APIRequestFactory, force_authenticate

from bloomerp.files.access import FileAccessManager
from bloomerp.filters.definition import FilterCondition
from bloomerp.models import FileNode, FileReference
from bloomerp.permissions.definition import BloomerpPermission, RowPolicyRuleContent
from bloomerp.permissions.manager import PolicyManager
from bloomerp.router import router
from bloomerp.tests.base import BloomerpAPIViewTestCase, ExpectedResult, RequestScenario
from bloomerp.views.mcp.link_file import AssistantFileLinkView


class TestAssistantFileLinkView(BloomerpAPIViewTestCase):
    """Cover the routed contract and stateful linking permission boundaries."""

    view_name = "api_assistant_file_link"
    auto_create_customers = False

    def extendedSetup(self) -> None:
        """Create synthetic file bytes and two independent destination rows."""
        self.customer = self.create_customer("Link", "Target", 30)
        self.other = self.create_customer("Other", "Target", 31)
        self.field = self.CustomerModel._meta.get_field("picture")
        self.file = FileNode.objects.create(
            content=SimpleUploadedFile("resume.txt", b"resume"), kind="FILE"
        )
        self.data = {
            "file_id": str(self.file.pk),
            "model_label": self.CustomerModel._meta.label,
            "object_id": str(self.customer.pk),
            "field": "picture",
        }

    def assigned(self, response: HttpResponse) -> bool:
        """Assert exact field ownership and unchanged source bytes."""
        self.assertEqual(response.json()["field"], "picture")
        reference = self.file.references.get()
        self.assertEqual(reference.application_field.field, "picture")
        self.assertEqual(reference.object_id, str(self.customer.pk))
        self.assertEqual(reference.created_by_id, self.admin_user.pk)
        self.assertEqual(FileNode.objects.count(), 1)
        self.assertEqual(self.file.content.read(), b"resume")
        return True

    def unchanged(self, response: HttpResponse) -> bool:
        """Assert rejected input leaves the source and references unchanged."""
        self.assertEqual(FileNode.objects.count(), 1)
        self.assertFalse(FileReference.objects.exists())
        return True

    def get_test_scenarios(self) -> list[RequestScenario]:
        """Exercise real routing and invalid destination/schema combinations."""
        scenarios = [
            RequestScenario(
                name="Link existing bytes directly to a dedicated field",
                method="POST",
                user=self.admin_user,
                content_type="application/json",
                data=self.data,
                expected=ExpectedResult(response_validators=self.assigned),
            )
        ]
        for name, data, status in [
            ("text field", {**self.data, "field": "first_name"}, 400),
            ("generic relation", {**self.data, "field": "files"}, 400),
            ("unknown field", {**self.data, "field": "missing"}, 400),
            ("unknown model", {**self.data, "model_label": "missing.Model"}, 400),
            ("invalid object", {**self.data, "object_id": "invalid"}, 400),
            (
                "missing object",
                {k: v for k, v in self.data.items() if k != "object_id"},
                400,
            ),
            ("empty field", {**self.data, "field": ""}, 400),
            ("null field", {**self.data, "field": None}, 400),
        ]:
            scenarios.append(
                RequestScenario(
                    name=f"Reject {name}",
                    method="POST",
                    user=self.admin_user,
                    content_type="application/json",
                    data=data,
                    expected=ExpectedResult(
                        status_code=status, response_validators=self.unchanged
                    ),
                )
            )
        return scenarios

    def link(self, data: dict[str, Any] | None = None, user: Any = None) -> Response:
        """Call the actual view for multi-step rollback and idempotency checks."""
        request = APIRequestFactory().post("/", data or self.data, format="json")
        force_authenticate(request, user=user or self.admin_user)
        return AssistantFileLinkView.as_view()(request)

    def grant(self, fields: list[str], permissions: list[BloomerpPermission]) -> Any:
        """Grant only the selected destination row and fields to the normal user."""
        policy = PolicyManager.create_policy(
            model_or_content_type=self.CustomerModel,
            field_permissions={field: permissions for field in fields},
            row_permissions=[
                RowPolicyRuleContent(
                    permissions=permissions,
                    conditions=[
                        FilterCondition(
                            field_path="id",
                            lookup_id="equals",
                            value=str(self.customer.pk),
                        )
                    ],
                )
            ],
        )
        policy.users.add(self.normal_user)
        return policy

    def test_idempotency_and_preserved_generic_references(self) -> None:
        """Repeat a full single-field link without writing storage or losing other uses."""
        FileReference.objects.create(file=self.file, content_object=self.customer)
        FileReference.objects.create(file=self.file, content_object=self.other)
        storage = self.file.content.storage
        with (
            patch.object(storage, "save", wraps=storage.save) as save,
            patch.object(
                storage, "open", side_effect=AssertionError("Must not read bytes")
            ),
        ):
            for _ in range(2):
                result = self.link()
                self.assertEqual(result.status_code, 200, result.data)
            save.assert_not_called()
        self.assertEqual(self.file.references.count(), 3)
        self.assertEqual(FileNode.objects.count(), 1)
        result = self.link({k: v for k, v in self.data.items() if k != "field"})
        self.assertEqual(result.status_code, 200)
        self.assertIsNone(result.data["field"])
        self.assertEqual(self.file.references.count(), 3)

    def test_single_and_multiple_cardinality(self) -> None:
        """Reject replacement, append within limits, and repeat safely at capacity."""
        second = FileNode.objects.create(
            content=SimpleUploadedFile("second.txt", b"two"), kind="FILE"
        )
        third = FileNode.objects.create(
            content=SimpleUploadedFile("third.txt", b"three"), kind="FILE"
        )
        self.assertEqual(self.link().status_code, 200)
        data = {**self.data, "file_id": str(second.pk)}
        self.assertEqual(self.link(data).status_code, 400)
        with (
            patch.object(self.field, "multiple", True),
            patch.object(self.field, "max_files", 2),
        ):
            self.assertEqual(self.link(data).status_code, 200)
            self.assertEqual(self.link(data).status_code, 200)
            self.assertEqual(
                self.link({**self.data, "file_id": str(third.pk)}).status_code, 400
            )
        self.assertEqual(FileReference.objects.count(), 2)
        self.assertEqual(FileNode.objects.count(), 3)

    def test_size_extension_and_missing_content(self) -> None:
        """Validate actual storage size, reject missing bytes, and preserve records."""
        self.file.meta["size"] = 1
        self.file.save(update_fields=["meta"])
        self.file.refresh_from_db()
        self.assertEqual(self.file.metadata.size, 1)
        for attribute, value in [("max_file_size", 5), ("allowed_extensions", ["pdf"])]:
            with (
                self.subTest(attribute=attribute),
                patch.object(self.field, attribute, value),
            ):
                self.assertEqual(self.link().status_code, 400)
        with patch.object(
            self.file.content.storage, "size", side_effect=FileNotFoundError
        ):
            self.assertEqual(self.link().status_code, 400)
        self.assertFalse(FileReference.objects.exists())
        with patch.object(self.field, "max_file_size", 6):
            self.assertEqual(self.link().status_code, 200)

    def test_source_and_destination_field_permissions(self) -> None:
        """Require independent source access and destination VIEW/CHANGE on the right row."""
        permissions = [BloomerpPermission.VIEW, BloomerpPermission.CHANGE]
        policy = self.grant(["picture"], permissions)
        self.assertEqual(self.link(user=self.normal_user).status_code, 403)
        self.normal_user.user_permissions.add(
            *Permission.objects.filter(
                content_type=ContentType.objects.get_for_model(FileNode),
                codename="view_filenode",
            )
        )
        self.normal_user = type(self.normal_user).objects.get(pk=self.normal_user.pk)
        policy.delete()
        for fields, grants in [
            (["files"], permissions),
            (["picture"], [BloomerpPermission.VIEW]),
            (["picture"], [BloomerpPermission.CHANGE]),
        ]:
            policy = self.grant(fields, grants)
            self.assertEqual(self.link(user=self.normal_user).status_code, 403)
            policy.delete()
        self.grant(["picture"], permissions)
        self.assertEqual(
            self.link(
                {**self.data, "object_id": str(self.other.pk)}, self.normal_user
            ).status_code,
            403,
        )
        self.assertFalse(FileReference.objects.exists())
        response = self.link(user=self.normal_user)
        self.assertEqual(response.status_code, 200, response.data)

    def test_failed_reference_write_preserves_existing_state(self) -> None:
        """Roll back a failing insert without deleting reusable source records or bytes."""
        manager = FileReference.objects
        original = manager.get_or_create

        def create_then_fail(**kwargs: Any) -> None:
            """Simulate failure after an insert inside the service transaction."""
            original(**kwargs)
            raise RuntimeError("reference failed")

        with (
            patch.object(manager, "get_or_create", side_effect=create_then_fail),
            self.assertRaisesRegex(RuntimeError, "reference failed"),
        ):
            self.link()
        self.assertFalse(FileReference.objects.exists())
        self.assertEqual(FileNode.objects.count(), 1)
        self.assertEqual(self.file.content.read(), b"resume")

    def test_mcp_schema_exposes_optional_field(self) -> None:
        """Keep a stable discovery contract for existing-file field assignment."""
        tool = next(
            route.mcp
            for route in router.get_mcp_routes()
            if route.mcp_tool_name == self.view_name
        )
        schema = tool.get_input_schema()
        self.assertIn("field", schema["properties"])
        self.assertNotIn("field", schema["required"])
        self.assertTrue(tool.idempotent_hint)
        self.assertFalse(tool.destructive_hint)

    def test_source_access_is_rechecked_after_target_lock(self) -> None:
        """Reject source visibility lost while waiting for destination serialization."""
        with patch.object(
            FileAccessManager, "can_read_file_node", side_effect=[True, False]
        ):
            self.assertEqual(self.link().status_code, 403)
        self.assertFalse(FileReference.objects.exists())

    def test_generic_mcp_field_link_round_trip(self) -> None:
        """Link and repeat through the real generic MCP transport and output schema."""
        self.client.force_login(self.admin_user)
        for arguments in [
            self.data,
            self.data,
            {k: v for k, v in self.data.items() if k != "field"},
        ]:
            response = self.client.post(
                reverse("mcp"),
                {
                    "jsonrpc": "2.0",
                    "id": 1,
                    "method": "tools/call",
                    "params": {
                        "name": self.view_name,
                        "arguments": arguments,
                    },
                },
                content_type="application/json",
                headers={
                    "Accept": "application/json, text/event-stream",
                    "MCP-Protocol-Version": "2025-11-25",
                },
            )
            result = response.json()["result"]
            self.assertFalse(result.get("isError", False), result)
            self.assertEqual(
                result["structuredContent"]["field"], arguments.get("field")
            )
            self.assertEqual(result["structuredContent"]["file_id"], str(self.file.pk))
        self.assertEqual(FileReference.objects.count(), 2)

    def test_invalid_renamed_source_has_structured_error(self) -> None:
        """Reject display names unsupported by upload validation without a server error."""
        for name in [".", "..", "folder/"]:
            with self.subTest(name=name):
                self.file.name = name
                self.file.save(update_fields=["name"])
                response = self.link()
                self.assertEqual(response.status_code, 400)
                self.assertIn("file_id", response.data)
        self.assertFalse(FileReference.objects.exists())
